=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters.
// Implements interface_spec.md / microarchitecture.md (rr_arbiter).
// Requirement: Create a round-robin arbiter for four requesters (N defaults to 4).
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant
);
    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    // State: priority pointer, index of the highest-priority requester.
    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;

    // Grant: masked priority encoder (equivalent of the wrapping search).
    // mask has bits ptr..N-1 set; requests there win first, lowest index
    // first; otherwise the lowest raw request wins (the wrap from N-1 to 0).
    wire [N-1:0] mask    = {N{1'b1}} << ptr;
    wire [N-1:0] req_hi  = req & mask;
    wire [N-1:0] pick_hi = req_hi & (-req_hi);
    wire [N-1:0] pick_lo = req & (-req);

    assign grant = (|req_hi) ? pick_hi : pick_lo;

    // Next pointer: one past the winner, wrapping at N (grant[N-1] -> 0).
    wire [N-1:0] grant_rot = {grant[N-2:0], grant[N-1]};

    integer i;
    always @(*) begin
        ptr_nxt = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (grant_rot[i]) begin
                ptr_nxt = i[PW-1:0];
            end
        end
    end

    // Pointer register: synchronous active-low reset to 0; holds with no grant.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5). Not proven
    // in this task; a SymbiYosys job file is still to be written.
    localparam integer LAST = N - 1;

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    initial assume (!rst_n);

    function integer f_dist;
        input integer from_idx;
        input integer to_idx;
        begin
            f_dist = (to_idx >= from_idx) ? (to_idx - from_idx)
                                          : (to_idx + N - from_idx);
        end
    endfunction

    always @(*) begin
        assert ((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}});
        assert ((grant & ~req) == {N{1'b0}});
        assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
        if (f_past_valid) begin
            assert (ptr <= LAST);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == {PW{1'b0}});
            end else if ($past(grant) == {N{1'b0}}) begin
                assert (ptr == $past(ptr));
            end
        end
    end

    genvar fj, fk;
    generate
        for (fj = 0; fj < N; fj = fj + 1) begin : g_formal
            reg [31:0] wait_cnt;
            initial wait_cnt = 32'd0;
            always @(posedge clk) begin
                if (!rst_n || !req[fj] || grant[fj]) begin
                    wait_cnt <= 32'd0;
                end else begin
                    wait_cnt <= wait_cnt + 32'd1;
                end
            end

            always @(*) begin
                if (f_past_valid) begin
                    assert (wait_cnt <= LAST);
                    assert (wait_cnt + f_dist(ptr, fj) <= LAST);
                end
            end

            always @(posedge clk) begin
                if (f_past_valid && $past(rst_n) && $past(grant[fj])) begin
                    assert (ptr == ((fj == LAST) ? 0 : fj + 1));
                end
            end

            for (fk = 0; fk < N; fk = fk + 1) begin : g_order
                always @(*) begin
                    if (f_past_valid && grant[fj] && req[fk]) begin
                        assert (f_dist(ptr, fk) >= f_dist(ptr, fj));
                    end
                end
            end
        end
    endgenerate
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb: self-checking testbench for rr_arbiter at N=4 and N=5.
// Checks every cycle against a reference pointer model, checks fairness with
// per-requester wait counters, and fails the run if a required case is not
// reached. Prints one NIRMAAN-SIM verdict line just before $finish.
`default_nettype none

module rr_arbiter_tb;
    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    wire [3:0] g4;
    reg  [4:0] req5;
    wire [4:0] g5;

    rr_arbiter #(.N(4)) u_n4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(g4));
    rr_arbiter #(.N(5)) u_n5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(g5));

    integer passed;
    integer failed;
    integer cyc;
    integer ptr4;
    integer ptr5;
    integer wait4 [0:3];
    integer wait5 [0:4];
    reg     ref_valid;
    reg     released;
    reg [7:0] e4;
    reg [7:0] e5;
    reg [3:0] s_g4;
    reg [4:0] s_g5;
    reg [3:0] prev_req4;
    reg [4:0] prev_req5;
    reg     rot_en;
    integer rot;
    reg     held_en;

    reg       cov_none4;
    reg       cov_none5;
    reg       cov_all4;
    reg       cov_all5;
    reg [3:0] cov_alone4;
    reg [4:0] cov_alone5;
    reg       cov_held4;
    reg       cov_held5;
    reg       cov_wait4;
    reg       cov_wait5;
    reg       cov_rst4;
    reg       cov_rst5;

    reg [8*64-1:0] nonce;
    integer n_ok;
    integer seed;
    reg [31:0] rnd;
    integer j;

    // Reference model: first requester at or after p, wrapping at n.
    function [7:0] exp_grant;
        input [7:0]   r;
        input integer p;
        input integer n;
        integer k;
        integer idx;
        reg     found;
        begin
            exp_grant = 8'd0;
            found = 1'b0;
            for (k = 0; k < n; k = k + 1) begin
                idx = p + k;
                if (idx >= n) idx = idx - n;
                if (!found && r[idx]) begin
                    found = 1'b1;
                    exp_grant[idx] = 1'b1;
                end
            end
        end
    endfunction

    task check_dut;
        input integer n;
        input [7:0]   r;
        input [7:0]   g;
        input integer p;
        output [7:0]  e;
        begin
            e = exp_grant(r, p, n);
            if (g === e) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req=%b ptr=%0d grant=%b, reference expects %b",
                       n, cyc, r, p, g, e);
            end
            if ((g & (g - 8'd1)) == 8'd0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: grant=%b is not one-hot or zero", n, cyc, g);
            end
            if ((g & ~r) == 8'd0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: grant=%b given to a non-requester (req=%b)",
                       n, cyc, g, r);
            end
            if ((r == 8'd0) || (g != 8'd0)) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req=%b but no grant (not work conserving)",
                       n, cyc, r);
            end
        end
    endtask

    task sample_cov;
        integer k;
        begin
            if (rst_n) released = 1'b1;
            if (rst_n && (req4 == 4'b0000)) cov_none4 = 1'b1;
            if (rst_n && (req5 == 5'b00000)) cov_none5 = 1'b1;
            if (rst_n && (req4 == 4'b1111)) cov_all4 = 1'b1;
            if (rst_n && (req5 == 5'b11111)) cov_all5 = 1'b1;
            for (k = 0; k < 4; k = k + 1)
                if (rst_n && (req4 == (4'b0001 << k))) cov_alone4[k] = 1'b1;
            for (k = 0; k < 5; k = k + 1)
                if (rst_n && (req5 == (5'b00001 << k))) cov_alone5[k] = 1'b1;
            if (!rst_n && released && (req4 != 4'b0000)) cov_rst4 = 1'b1;
            if (!rst_n && released && (req5 != 5'b00000)) cov_rst5 = 1'b1;
            if (held_en && rst_n && req4[2] && (wait4[2] > 0) &&
                ((req4 & 4'b1011) != (prev_req4 & 4'b1011)))
                cov_held4 = 1'b1;
            if (held_en && rst_n && req5[3] && (wait5[3] > 0) &&
                ((req5 & 5'b10111) != (prev_req5 & 5'b10111)))
                cov_held5 = 1'b1;
        end
    endtask

    task check_rotation;
        begin
            if (g4 === (4'b0001 << (rot % 4))) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=4 cycle %0d: strict rotation step %0d expected grant %b, got %b",
                       cyc, rot, (4'b0001 << (rot % 4)), g4);
            end
            if (g5 === (5'b00001 << (rot % 5))) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=5 cycle %0d: strict rotation step %0d expected grant %b, got %b",
                       cyc, rot, (5'b00001 << (rot % 5)), g5);
            end
            rot = rot + 1;
        end
    endtask

    // Reference pointer and fairness update at the rising edge.
    task update_ref;
        integer k;
        integer w;
        reg     viol;
        begin
            if (!rst_n) begin
                ref_valid = 1'b1;
                ptr4 = 0;
                ptr5 = 0;
                for (k = 0; k < 4; k = k + 1) wait4[k] = 0;
                for (k = 0; k < 5; k = k + 1) wait5[k] = 0;
            end else if (ref_valid) begin
                w = -1;
                for (k = 0; k < 4; k = k + 1) if (e4[k]) w = k;
                if (w >= 0) ptr4 = (w == 3) ? 0 : w + 1;
                w = -1;
                for (k = 0; k < 5; k = k + 1) if (e5[k]) w = k;
                if (w >= 0) ptr5 = (w == 4) ? 0 : w + 1;

                viol = 1'b0;
                for (k = 0; k < 4; k = k + 1) begin
                    if (!req4[k] || s_g4[k]) wait4[k] = 0;
                    else wait4[k] = wait4[k] + 1;
                    if (wait4[k] > 3) begin
                        viol = 1'b1;
                        $error("N=4 cycle %0d: requester %0d has waited %0d cycles (limit 3)",
                               cyc, k, wait4[k]);
                    end
                    if (wait4[k] == 3) cov_wait4 = 1'b1;
                end
                if (viol) failed = failed + 1;
                else passed = passed + 1;

                viol = 1'b0;
                for (k = 0; k < 5; k = k + 1) begin
                    if (!req5[k] || s_g5[k]) wait5[k] = 0;
                    else wait5[k] = wait5[k] + 1;
                    if (wait5[k] > 4) begin
                        viol = 1'b1;
                        $error("N=5 cycle %0d: requester %0d has waited %0d cycles (limit 4)",
                               cyc, k, wait5[k]);
                    end
                    if (wait5[k] == 4) cov_wait5 = 1'b1;
                end
                if (viol) failed = failed + 1;
                else passed = passed + 1;
            end
        end
    endtask

    // One clock cycle: drive inputs while clk is low, check, then rising edge.
    task step;
        input       rst_in;
        input [3:0] r4;
        input [4:0] r5;
        begin
            clk   = 1'b0;
            rst_n = rst_in;
            req4  = r4;
            req5  = r5;
            #5;
            if (ref_valid) begin
                check_dut(4, {4'b0000, req4}, {4'b0000, g4}, ptr4, e4);
                check_dut(5, {3'b000, req5}, {3'b000, g5}, ptr5, e5);
                if (rot_en) check_rotation;
                sample_cov;
            end
            s_g4 = g4;
            s_g5 = g5;
            clk = 1'b1;
            update_ref;
            prev_req4 = req4;
            prev_req5 = req5;
            #5;
            cyc = cyc + 1;
        end
    endtask

    initial begin
        clk = 1'b0;
        rst_n = 1'b0;
        req4 = 4'b0000;
        req5 = 5'b00000;
        passed = 0;
        failed = 0;
        cyc = 0;
        ptr4 = 0;
        ptr5 = 0;
        for (j = 0; j < 4; j = j + 1) wait4[j] = 0;
        for (j = 0; j < 5; j = j + 1) wait5[j] = 0;
        ref_valid = 1'b0;
        released = 1'b0;
        e4 = 8'd0;
        e5 = 8'd0;
        s_g4 = 4'b0000;
        s_g5 = 5'b00000;
        prev_req4 = 4'b0000;
        prev_req5 = 5'b00000;
        rot_en = 1'b0;
        rot = 0;
        held_en = 1'b0;
        cov_none4 = 1'b0;
        cov_none5 = 1'b0;
        cov_all4 = 1'b0;
        cov_all5 = 1'b0;
        cov_alone4 = 4'b0000;
        cov_alone5 = 5'b00000;
        cov_held4 = 1'b0;
        cov_held5 = 1'b0;
        cov_wait4 = 1'b0;
        cov_wait5 = 1'b0;
        cov_rst4 = 1'b0;
        cov_rst5 = 1'b0;
        seed = 32'h1b70baad;
        rnd = 32'd0;
        nonce = {(8*64){1'b0}};
        n_ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (n_ok == 0) $display("rr_arbiter_tb: no nirmaan_nonce plusarg given");

        // Phase 1: reset, idle and with requests (grant follows req in reset).
        step(1'b0, 4'b0000, 5'b00000);
        step(1'b0, 4'b0000, 5'b00000);
        step(1'b0, 4'b1010, 5'b10100);

        // Phase 2: no requests.
        step(1'b1, 4'b0000, 5'b00000);
        step(1'b1, 4'b0000, 5'b00000);
        step(1'b1, 4'b0000, 5'b00000);

        // Phase 3: each requester alone.
        for (j = 0; j < 5; j = j + 1) begin
            step(1'b1, (j < 4) ? (4'b0001 << j) : 4'b0000, 5'b00001 << j);
            step(1'b1, (j < 4) ? (4'b0001 << j) : 4'b0000, 5'b00001 << j);
        end

        // Phase 4: reset during traffic, then everyone requesting: strict
        // rotation 0,1,..,N-1,0,... after reset and the longest fair wait.
        step(1'b0, 4'b1111, 5'b11111);
        rot_en = 1'b1;
        rot = 0;
        repeat (20) step(1'b1, 4'b1111, 5'b11111);
        rot_en = 1'b0;

        // Phase 5: a held request among changing others.
        held_en = 1'b1;
        repeat (60) begin
            rnd = $random(seed);
            step(1'b1, rnd[3:0] | 4'b0100, rnd[8:4] | 5'b01000);
        end
        held_en = 1'b0;

        // Phase 6: random contention with occasional reset during traffic.
        repeat (400) begin
            rnd = $random(seed);
            step((rnd[15:11] != 5'd0), rnd[3:0] | rnd[19:16], rnd[8:4] | rnd[24:20]);
        end

        // Phase 7: drain.
        step(1'b1, 4'b0000, 5'b00000);
        step(1'b1, 4'b0000, 5'b00000);

        // Coverage: every case required by the interface spec must be reached.
        if (cov_none4 && cov_none5) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: no-request case not reached"); end
        if ((&cov_alone4) && (&cov_alone5)) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: not every requester was seen alone"); end
        if (cov_all4 && cov_all5) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: everyone-requesting case not reached"); end
        if (cov_held4 && cov_held5) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: held request among changing others not reached"); end
        if (cov_wait4 && cov_wait5) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: longest fair wait (N-1) not reached"); end
        if (cov_rst4 && cov_rst5) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: reset during traffic not reached"); end
        if (rot >= 20) passed = passed + 1;
        else begin failed = failed + 1; $error("coverage: strict rotation phase did not run"); end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

`default_nettype wire
=== END FILE ===
